#!/usr/bin/env bash
# Question 1: Right-size ${Q1_NAME}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl get apiservice v1beta1.metrics.k8s.io >/dev/null 2>&1 || {
  echo "this cluster image has no metrics-server: rebuild images with ./cka images build --force" >&2
  exit 1
}
kubectl get crd verticalpodautoscalers.autoscaling.k8s.io >/dev/null 2>&1 || {
  echo "this cluster image has no Vertical Pod Autoscaler: rebuild images with ./cka images build --force" >&2
  exit 1
}
kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q1_NS}" delete vpa "${Q1_NAME}-vpa" --ignore-not-found >/dev/null
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: "${Q1_NAME}"
  namespace: "${Q1_NS}"
  labels:
    app: "${Q1_NAME}"
spec:
  replicas: 2
  selector:
    matchLabels:
      app: "${Q1_NAME}"
  template:
    metadata:
      labels:
        app: "${Q1_NAME}"
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports:
            - containerPort: 80
          resources:
            requests:
              cpu: 50m
              memory: 32Mi
        - name: log-agent
          image: busybox:1.36
          command:
            - sh
            - -c
            - while true; do sleep 30; done
          resources:
            requests:
              cpu: 10m
              memory: 16Mi
---
apiVersion: v1
kind: Service
metadata:
  name: "${Q1_NAME}"
  namespace: "${Q1_NS}"
spec:
  selector:
    app: "${Q1_NAME}"
  ports:
    - port: 80
EOF
